{% for row in doc.items %}
    {% if row.serial_no %}
        {% set serial_nos = row.serial_no.split(",") %}
        {% for sn in serial_nos %}
            {% set item_code = row.item_code %}
            {% set item_name = frappe.db.get_value("Item", item_code, "item_name") %}

            <table style="width:100% !important;">
                <tbody>
                    <tr>
                        <!--QR Code for Serial No-->
                        <td class="" style="font-size: 8px; width:50%; text-align:center;">
                            <div>
                                <img style="width:100%" src="http://bwipjs-api.metafloor.com/?bcid=qrcode&amp;text={{ sn.strip() }}">
                            </div>
                            <div>{{ sn.strip() }}</div>
                        </td>
                        <td style="width:50%"></td>
                    </tr>
                </tbody>
            </table>

            <div class="new-page"></div>
        {% endfor %}
    {% endif %}
{% endfor %}

{% for row in doc.items %}
{% for i in range(row.qty|int) %}

{% set item_code = row.item_code %}
{% set item_name = frappe.db.get_value("Item", item_code, "item_name") %}



<table style="width=50%; height: 100px;">
    <tbody>
        <tr>
            <!--QR Code for Item-->
            <td width="100%" class="" style="font-size: xx-small;">
                <div><img style="" src="http://bwipjs-api.metafloor.com/?bcid=qrcode&amp;text={{ item_code }}"></div>
                <div>{{item_code}}</div>
            </td>

        </tr>
    </tbody>
</table>

<div class="new-page"></div>











{% endfor %}
{% endfor %}

