html:
{{ letter_head }}

{% set lcv = doc %}

{% set ns = namespace(total_qty=0, total_amount=0, total_charges=0, total_pct=0, total_fcy=0, total_item_charges=0, total_amount_with_charges=0, fcy_symbol="", fcy_currency="-") %}

{% for item in lcv.items %}
{% set ns.total_qty = ns.total_qty + (item.qty or 0) %}
{% set ns.total_amount = ns.total_amount + (item.amount or 0) %}
{% endfor %}

{% set rate = doc.conversion_rate if doc.conversion_rate else 1 %}

{% for t in lcv.taxes %}
{% set ns.total_charges = ns.total_charges + (t.amount or 0) %}
{% endfor %}

{% set suppliers = [] %}
{% set supplier_names = [] %}

{% for pr in doc.purchase_receipts %}
{% if pr.receipt_document %}
{% set pr_doc = frappe.get_doc(pr.receipt_document_type, pr.receipt_document) %}

{% if pr_doc.supplier not in suppliers %}
{% set _ = suppliers.append(pr_doc.supplier) %}
{% set supplier_name_val = frappe.db.get_value("Supplier", pr_doc.supplier, "supplier_name") %}
{% set _ = supplier_names.append(supplier_name_val if supplier_name_val else pr_doc.supplier) %}
{% endif %}

{% if pr_doc.currency and ns.fcy_currency == "-" %}
{% set ns.fcy_currency = pr_doc.currency %}
{% set _sym = frappe.db.get_value("Currency", pr_doc.currency, "symbol") %}
{% set ns.fcy_symbol = _sym if _sym else pr_doc.currency %}
{% endif %}

{% endif %}
{% endfor %}

<style>

@page {
    size: A4 landscape;
    margin: 12mm 14mm 12mm 14mm;
}

@media print {
    body {
        width: 100%;
    }
}

body {
    font-family: "Inter", "Segoe UI", "Roboto", "Helvetica Neue", Arial, sans-serif;
    font-size: 11px;
    color: #333;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

h2, h4 {
    font-weight: 600;
    letter-spacing: 0.3px;
    color:#222;
}

table {
    border-collapse: collapse;
}

th {
    background: #f2f4f7;
    font-weight:600;
}

td, th {
    border:1px solid #d6d9de;
    padding:4px 6px;
}

hr {
    border:none;
    border-top:1px solid #d6d9de;
}

</style>

<!-- HEADER -->

<table style="width:100%; margin-bottom:8px;">
<tr>

<td style="vertical-align:top;">
<div style="text-align:center;">
<h2 style="font-size:15px;font-weight:700;text-transform:uppercase;margin:0;">
Landed Cost Voucher
</h2>

<div style="font-size:11px;color:#444;">
{{ doc.name }}
</div>

</div>
</td>

<td style="width:75px;text-align:right;">
<img src="https://api.qrserver.com/v1/create-qr-code/?size=65x65&data={{ doc.name }}" style="width:65px;height:65px;">
</td>

</tr>
</table>

<hr style="border-top:2px solid #222;margin:6px 0;">

<!-- META -->

<table style="width:100%; font-size:11px; margin-bottom:10px;">

<tr>
<td style="width:20%;font-weight:600;">Voucher No</td>
<td style="width:30%;">{{ doc.name }}</td>

<td style="width:20%;font-weight:600;">Posting Date</td>
<td style="width:30%;">{{ frappe.format(doc.posting_date, {'fieldtype':'Date'}) }}</td>
</tr>

<tr>
<td style="font-weight:600;">Company</td>
<td>{{ doc.company }}</td>

<td style="font-weight:600;">Status</td>
<td>
{% if doc.docstatus == 0 %}Draft
{% elif doc.docstatus == 1 %}Submitted
{% elif doc.docstatus == 2 %}Cancelled
{% endif %}
</td>
</tr>

<tr>
<td style="font-weight:600;">Distribution Method</td>
<td>{{ doc.distribute_charges_based_on or "-" }}</td>

<td style="font-weight:600;">Total Charges</td>
<td><b>{{ "{:,.0f}".format(ns.total_charges) }}</b></td>
</tr>

</table>

<hr style="border-top:1px solid #ccc;margin:6px 0;">

<!-- PURCHASE RECEIPTS -->

<h4 style="margin:6px 0;">Purchase Receipts / Invoices</h4>

<table style="width:100%; font-size:11px;">

<thead>
<tr>
<th style="text-align:center;">Sr</th>
<th>Receipt Type</th>
<th>Receipt Document</th>
<th>Supplier</th>
<th>Currency</th>
<th style="text-align:right;">Net Total</th>
<th style="text-align:right;">Net Total (PKR)</th>
</tr>
</thead>

<tbody>

{% for pr in doc.purchase_receipts %}

{% if pr.receipt_document %}
{% set pr_doc = frappe.get_doc(pr.receipt_document_type, pr.receipt_document) %}
{% set sup_name = frappe.db.get_value("Supplier", pr_doc.supplier, "supplier_name") %}
{% set pr_currency = pr_doc.currency if pr_doc.currency else "-" %}
{% set pr_net_total = pr_doc.net_total if pr_doc.net_total else 0 %}
{% set pr_base_net_total = pr_doc.base_net_total if pr_doc.base_net_total else 0 %}
{% set _pr_sym = frappe.db.get_value("Currency", pr_doc.currency, "symbol") if pr_doc.currency else "" %}
{% set pr_currency_symbol = _pr_sym if _pr_sym else pr_doc.currency if pr_doc.currency else "" %}
{% else %}
{% set pr_doc = none %}
{% set sup_name = "-" %}
{% set pr_currency = "-" %}
{% set pr_net_total = 0 %}
{% set pr_currency_symbol = "" %}
{% set pr_base_net_total = 0 %}
{% endif %}

<tr>
<td style="text-align:center;">{{ loop.index }}</td>
<td>{{ pr.receipt_document_type }}</td>
<td><b>{{ pr.receipt_document }}</b></td>
<td>{{ sup_name if sup_name else pr_doc.supplier if pr_doc else "-" }}</td>
<td>{{ pr_currency }}</td>
<td style="text-align:right;">{{ pr_currency_symbol }} {{ "{:,.2f}".format(pr_net_total) }}</td>
<td style="text-align:right;">{{ "{:,.2f}".format(pr_base_net_total) }}</td>
</tr>

{% endfor %}

</tbody>
</table>

<!-- ITEMS -->

<h4 style="margin-top:10px;">Items Cost Analysis</h4>

<table style="width:100%; font-size:11px;">

<thead>
<tr>

<th>Item</th>
<th>Description</th>
<th style="text-align:center;">Qty</th>
<th style="text-align:right;">Rate</th>
<th style="text-align:right;">FCY ({{ ns.fcy_symbol }} {{ ns.fcy_currency }})</th>
<th style="text-align:right;">Amount</th>
<th style="text-align:right;">Charges / Unit</th>
<th style="text-align:right;">Total Cost / Unit</th>
<th style="text-align:right;">Charges</th>
<th style="text-align:right;">Total Amount + Charges</th>

</tr>
</thead>

<tbody>

{% for item in doc.items %}

{% set qty = item.qty or 0 %}
{% set charges = item.applicable_charges or 0 %}

{% if qty > 0 %}
{% set charge_unit = charges / qty %}
{% else %}
{% set charge_unit = 0 %}
{% endif %}

{% set total_cost_unit = (item.rate or 0) + charge_unit %}
{% set total_with_charges = (item.amount or 0) + charges %}

{# Fetch actual FCY amount from the source Purchase Receipt item #}
{% set fcy_value = 0 %}
{% set item_fcy_symbol = ns.fcy_symbol %}
{% if item.purchase_receipt_item %}
{% set pr_item_doctype = "Purchase Receipt Item" %}
{% set pr_item_amount = frappe.db.get_value(pr_item_doctype, item.purchase_receipt_item, "amount") %}
{% set pr_item_parent = frappe.db.get_value(pr_item_doctype, item.purchase_receipt_item, "parent") %}
{% if pr_item_amount is not none %}
{% set fcy_value = pr_item_amount or 0 %}
{% endif %}
{% if pr_item_parent %}
{% set pr_currency = frappe.db.get_value("Purchase Receipt", pr_item_parent, "currency") %}
{% if pr_currency %}
{% set _sym = frappe.db.get_value("Currency", pr_currency, "symbol") %}
{% set item_fcy_symbol = _sym if _sym else pr_currency %}
{% endif %}
{% endif %}
{% endif %}
{# Fallback: back-calculate if no PR item link found #}
{% if fcy_value == 0 %}
{% set fcy_value = total_with_charges / rate if rate else total_with_charges %}
{% set item_fcy_symbol = ns.fcy_symbol %}
{% endif %}

{% set ns.total_item_charges = ns.total_item_charges + charges %}
{% set ns.total_amount_with_charges = ns.total_amount_with_charges + total_with_charges %}
{% set ns.total_fcy = ns.total_fcy + fcy_value %}

<tr>

<td><b>{{ item.item_code }}</b></td>

<td style="max-width:180px;word-wrap:break-word;white-space:normal;">
{{ item.description or "-" }}
</td>

<td style="text-align:center;">{{ qty }}</td>

<td style="text-align:right;">
{{ "{:,.0f}".format(item.rate or 0) }}
</td>

<td style="text-align:right;">
{{ "{:,.2f}".format(fcy_value) }}
</td>

<td style="text-align:right;">
{{ "{:,.0f}".format(item.amount or 0) }}
</td>

<td style="text-align:right;">
{{ "{:,.0f}".format(charge_unit) }}
</td>

<td style="text-align:right;">
{{ "{:,.0f}".format(total_cost_unit) }}
</td>

<td style="text-align:right;">
{{ "{:,.0f}".format(charges) }}
</td>

<td style="text-align:right;">
{{ "{:,.0f}".format(total_with_charges) }}
</td>

</tr>

{% endfor %}

<!-- TOTAL ROW -->
<tr style="font-weight:700;background:#f4f4f4;">
<td colspan="2" style="text-align:right;">TOTAL</td>
<td style="text-align:center;">{{ ns.total_qty }}</td>
<td></td>
<td style="text-align:right;">{{ "{:,.2f}".format(ns.total_fcy) }}</td>
<td style="text-align:right;">{{ "{:,.0f}".format(ns.total_amount) }}</td>
<td colspan="2"></td>
<td style="text-align:right;">{{ "{:,.0f}".format(ns.total_item_charges) }}</td>
<td style="text-align:right;">{{ "{:,.0f}".format(ns.total_amount_with_charges) }}</td>
</tr>

</tbody>

</table>

<!-- EXPENSE HEADS -->

<h4 style="margin-top:10px;">Applicable Charges — Expense Account Heads</h4>

<table style="width:100%; font-size:11px;">

<thead>
<tr>
<th>Expense Account Head</th>
<th>Description</th>
<th style="text-align:right;">Amount</th>
<th style="text-align:right;">Base Amount</th>
<th style="text-align:right;">% Share</th>
</tr>
</thead>

<tbody>

{% for tax in doc.taxes %}

{% set pct = (tax.amount / ns.total_charges * 100) if ns.total_charges else 0 %}
{% set ns.total_pct = ns.total_pct + pct %}

<tr>

<td><b>{{ tax.expense_account }}</b></td>

<td>{{ tax.description }}</td>

<td style="text-align:right;">
{{ "{:,.0f}".format(tax.amount) }}
</td>

<td style="text-align:right;">
{{ "{:,.0f}".format(tax.base_amount) }}
</td>

<td style="text-align:right;">
{{ "%.0f"|format(pct) }}%
</td>

</tr>

{% endfor %}

<tr style="font-weight:700;background:#f4f4f4;">
<td colspan="2" style="text-align:right;">TOTAL</td>

<td style="text-align:right;">
{{ "{:,.0f}".format(ns.total_charges) }}
</td>

<td style="text-align:right;">
{{ "{:,.0f}".format(ns.total_charges) }}
</td>

<td style="text-align:right;">
{{ "%.0f"|format(ns.total_pct) }}%
</td>

</tr>

</tbody>

</table>

<!-- REMARKS -->

{% if doc.remarks %}

<div style="margin-top:8px;font-size:11px;border-left:3px solid #333;padding:6px;background:#f9f9f9;">
<b>Remarks:</b> {{ doc.remarks }}
</div>

{% endif %}

<!-- SIGNATURES -->

<table style="width:100%;text-align:center;font-size:11px;margin-top:15px;">

<tr>

<td style="width:33%;padding:0 20px;">
<div style="border-top:1px solid #222;margin-top:40px;padding-top:5px;">
Prepared By
</div>
</td>

<td style="width:33%;padding:0 20px;">
<div style="border-top:1px solid #222;margin-top:40px;padding-top:5px;">
Checked By
</div>
</td>

<td style="width:33%;padding:0 20px;">
<div style="border-top:1px solid #222;margin-top:40px;padding-top:5px;">
Approved By
</div>
</td>

</tr>

</table>

{% set contact = frappe.get_all("Contact",
    filters={"link_name": doc.for_customer or doc.customer},
    fields=["first_name","last_name","email_id","mobile_no"],
    limit=1
) %}
{% set contact = contact[0] if contact else None %}

{% set address = frappe.get_doc("Address", doc.for_customer_address) if doc.for_customer_address else None %}

<style>
    * {
        font-family: "Segoe UI", Arial, sans-serif;
        font-size: 11px;
        box-sizing: border-box;
        margin: 0;
        padding: 0;
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }

    body {
        color: #1a1a2e;
    }

    /* ── HEADER ── */
    .letterhead-wrap {
        text-align: center;
        margin-bottom: 6px;
    }

    .doc-title-bar {
        background: #0a2351 !important;
        color: #ffffff !important;
        padding: 8px 14px;
        display: flex;
        justify-content: space-between;
        align-items: center;
        border-radius: 3px;
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }

    .doc-title-bar .doc-label {
        font-size: 15px;
        font-weight: 700;
        letter-spacing: 1px;
    }

    .doc-title-bar .doc-meta {
        text-align: right;
        font-size: 11px;
        line-height: 1.6;
    }

    .qr-wrap {
        margin-left: 12px;
    }

    /* ── INFO GRID ── */
    .info-grid {
        width: 100%;
        border-collapse: collapse;
        margin-top: 10px;
    }

    .info-grid td {
        vertical-align: top;
        padding: 8px 10px;
        width: 50%;
    }

    .info-block-title {
        background: #0a2351 !important;
        color: #ffffff !important;
        font-weight: 700;
        font-size: 10px;
        letter-spacing: 0.5px;
        padding: 4px 8px;
        margin-bottom: 5px;
        border-radius: 2px;
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }

    .info-block-body {
        border: 1px solid #c5d3e8;
        padding: 7px 9px;
        border-radius: 2px;
        line-height: 1.8;
        min-height: 70px;
    }

    .info-block-body b {
        color: #0a2351;
    }

    /* ── SECTION HEADING ── */
    .section-heading {
        background: #0a2351 !important;
        color: #ffffff !important;
        font-weight: 700;
        font-size: 11px;
        letter-spacing: 0.5px;
        padding: 5px 10px;
        margin-top: 12px;
        margin-bottom: 0;
        border-radius: 2px 2px 0 0;
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }

    /* ── ITEMS TABLE ── */
    .items-table {
        width: 100%;
        border-collapse: collapse;
        font-size: 11px;
    }

    .items-table thead tr {
        background: #1a3a6b !important;
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }

    .items-table thead th {
        padding: 6px 8px;
        text-align: left;
        font-weight: 700;
        color: #ffffff !important;
        background: #1a3a6b !important;
        border: 1px solid #2a4a7b;
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }

    .items-table thead th.right {
        text-align: right;
    }

    .items-table tbody tr:nth-child(even) {
        background: #eef2f9;
    }

    .items-table tbody tr:nth-child(odd) {
        background: #ffffff;
    }

    .items-table tbody td {
        padding: 6px 8px;
        border: 1px solid #c5d3e8;
        vertical-align: top;
    }

    .items-table tbody td.right {
        text-align: right;
    }

    .items-table tbody td.center {
        text-align: center;
    }

    /* ── QTY BADGES ── */
    .badge {
        display: inline-block;
        padding: 1px 6px;
        border-radius: 3px;
        font-weight: 600;
        font-size: 10px;
    }

    .badge-ordered  { background: #d6e4ff; color: #0a2351; }
    .badge-issued   { background: #d4edda; color: #155724; }
    .badge-remaining-zero { background: #d4edda; color: #155724; }
    .badge-remaining-some { background: #fff3cd; color: #856404; }
    .badge-remaining-full { background: #f8d7da; color: #721c24; }

    /* ── TOTALS STRIP ── */
    .totals-strip {
        width: 100%;
        border-collapse: collapse;
        margin-top: 10px;
    }

    .totals-strip td {
        padding: 5px 10px;
        vertical-align: top;
    }

    .totals-left {
        width: 55%;
    }

    .totals-right {
        width: 45%;
        text-align: right;
    }

    .total-line {
        display: flex;
        justify-content: space-between;
        padding: 3px 0;
        border-bottom: 1px solid #c5d3e8;
    }

    .total-line:last-child {
        border-bottom: none;
    }

    .grand-total-line {
        background: #0a2351;
        color: #ffffff;
        padding: 5px 9px;
        border-radius: 2px;
        display: flex;
        justify-content: space-between;
        font-size: 13px;
        font-weight: 700;
        margin-top: 4px;
    }

    /* ── ISSUANCE SUMMARY ── */
    .issuance-box {
        border: 1px solid #c5d3e8;
        border-radius: 3px;
        padding: 8px 10px;
        margin-top: 4px;
        background: #f5f8ff;
    }

    .issuance-row {
        display: flex;
        justify-content: space-between;
        padding: 2px 0;
        border-bottom: 1px dashed #c5d3e8;
    }

    .issuance-row:last-child {
        border-bottom: none;
    }

    .issuance-label {
        color: #0a2351;
        font-weight: 600;
    }

    /* ── SIGNATURES ── */
    .signatures {
        width: 100%;
        margin-top: 50px;
        border-collapse: collapse;
    }

    .signatures td {
        width: 33.3%;
        text-align: center;
        vertical-align: bottom;
        padding: 0 10px;
    }

    .sig-name {
        font-weight: 700;
        font-size: 11px;
        margin-bottom: 4px;
        min-height: 18px;
    }

    .sig-line {
        border-top: 1px solid #0a2351;
        width: 200px;
        margin: 0 auto;
    }

    .sig-label {
        margin-top: 4px;
        color: #0a2351;
        font-size: 10px;
        font-weight: 600;
        letter-spacing: 0.3px;
    }

    /* ── STATUS STAMP ── */
    .status-stamp {
        display: inline-block;
        border: 2px solid;
        padding: 2px 8px;
        border-radius: 3px;
        font-weight: 700;
        font-size: 10px;
        letter-spacing: 1px;
    }

    .status-pending   { border-color: #e67e00; color: #e67e00; }
    .status-partial   { border-color: #1a6fbf; color: #1a6fbf; }
    .status-issued    { border-color: #1a8a3a; color: #1a8a3a; }
    .status-cancelled { border-color: #c0392b; color: #c0392b; }
</style>

<!-- ═══════════════════════════════════════════════════════════
     LETTER HEAD
════════════════════════════════════════════════════════════ -->
<div class="letterhead-wrap">
    {{ letter_head }}
</div>

<!-- ═══════════════════════════════════════════════════════════
     TITLE BAR
════════════════════════════════════════════════════════════ -->
<div class="doc-title-bar">

    <div class="doc-label">MATERIAL REQUEST</div>

    <div style="display:flex; align-items:center;">

        <div class="doc-meta">
            <div><b style="color:#a8c4e8;">Voucher:</b> {{ doc.name }}</div>
            <div><b style="color:#a8c4e8;">Date:</b> {{ frappe.utils.format_date(doc.transaction_date) }}</div>
            {% if doc.schedule_date %}
            <div><b style="color:#a8c4e8;">Required By:</b> {{ frappe.utils.format_date(doc.schedule_date) }}</div>
            {% endif %}
            <div><b style="color:#a8c4e8;">Purpose:</b> {{ doc.material_request_type }}</div>
        </div>

        <div class="qr-wrap">
            <img style="width:64px; height:64px; display:block;"
                src="https://api.qrserver.com/v1/create-qr-code/?size=64x64&data={{ frappe.utils.get_url() }}/app/material-request/{{ doc.name }}">
        </div>

    </div>

</div>

<!-- ═══════════════════════════════════════════════════════════
     INFO GRID
════════════════════════════════════════════════════════════ -->
<table class="info-grid">
<tr>

    <!-- LEFT — Customer / Requested For -->
    <td style="padding-right:6px;">
        <div class="info-block-title">REQUESTED FOR</div>
        <div class="info-block-body">

            {% if doc.for_customer_name or doc.for_customer %}
            <b>Customer:</b> {{ doc.for_customer_name or doc.for_customer }}<br>
            {% endif %}

            {% if address %}
                {% set addr_parts = [address.address_line1, address.address_line2, address.city, address.state, address.country] | select | list %}
                {% if addr_parts %}
                <b>Address:</b> {{ addr_parts | join(", ") }}<br>
                {% endif %}
            {% endif %}

            {% if contact %}
                {% set cname = ((contact.first_name or "") ~ " " ~ (contact.last_name or "")).strip() %}
                {% if cname %}<b>Contact:</b> {{ cname }}<br>{% endif %}
                {% if contact.email_id %}<b>Email:</b> {{ contact.email_id }}<br>{% endif %}
                {% if contact.mobile_no %}<b>Phone:</b> {{ contact.mobile_no }}<br>{% endif %}
            {% endif %}

            {% if not (doc.for_customer_name or doc.for_customer or address or contact) %}
            <span style="color:#888;">—</span>
            {% endif %}

        </div>
    </td>

    <!-- RIGHT — Order Details -->
    <td style="padding-left:6px;">
        <div class="info-block-title">ORDER DETAILS</div>
        <div class="info-block-body">

            {% if doc.project %}
            <b>Project:</b> {{ doc.project }}<br>
            {% endif %}

            {% if doc.set_warehouse %}
            <b>Target Warehouse:</b> {{ doc.set_warehouse }}<br>
            {% endif %}

            {% if doc.set_from_warehouse %}
            <b>Source Warehouse:</b> {{ doc.set_from_warehouse }}<br>
            {% endif %}

            {% if doc.supplier_name or doc.supplier %}
            <b>Supplier:</b> {{ doc.supplier_name or doc.supplier }}<br>
            {% endif %}

            <b>Status:</b>
            {% if doc.status == "Pending" %}
                <span class="status-stamp status-pending">PENDING</span>
            {% elif doc.status == "Partially Ordered" %}
                <span class="status-stamp status-partial">PARTIAL</span>
            {% elif doc.status == "Ordered" or doc.status == "Transferred" or doc.status == "Issued" %}
                <span class="status-stamp status-issued">COMPLETE</span>
            {% elif doc.status == "Cancelled" %}
                <span class="status-stamp status-cancelled">CANCELLED</span>
            {% else %}
                {{ doc.status }}
            {% endif %}
            <br>

            <b>Requested On:</b> {{ frappe.utils.format_date(doc.transaction_date) }}<br>

        </div>
    </td>

</tr>
</table>

<!-- ═══════════════════════════════════════════════════════════
     ITEMS TABLE
════════════════════════════════════════════════════════════ -->
<div class="section-heading">ITEMS</div>

<table class="items-table">
    <thead>
        <tr>
            <th style="width:4%;">Sr.</th>
            <th style="width:14%;">Item Code</th>
            <th style="width:32%;">Item Detail</th>
            <th style="width:12%;">Warehouse</th>
            <th style="width:10%;" class="right">Qty Ordered</th>
            <th style="width:10%;" class="right">Issued Qty</th>
            <th style="width:10%;" class="right">Remaining Qty</th>
            <th style="width:8%;" class="center">UOM</th>
        </tr>
    </thead>
    <tbody>
        {% for row in doc.items %}
        {% set issued = row.custom_issued_qty or 0 %}
        {% set remaining = row.custom_remaining_qty if row.custom_remaining_qty is not none else (row.qty - issued) %}
        <tr>

            <td class="center">{{ loop.index }}</td>

            <td>{{ row.item_code }}</td>

            <td>
                <b>{{ row.item_name or row.item_code }}</b>
                {% if row.manufacturer_part_no %}
                <div style="color:#555; margin-top:2px;">Part No: {{ row.manufacturer_part_no }}</div>
                {% endif %}
                {% if row.project %}
                <div style="color:#0a2351; font-size:10px; margin-top:2px;">Project: {{ row.project }}</div>
                {% endif %}
            </td>

            <td>{{ row.warehouse or "—" }}</td>

            <td class="right">
                <span class="badge badge-ordered">{{ row.qty | int if row.qty == (row.qty | int) else row.qty }}</span>
            </td>

            <td class="right">
                <span class="badge badge-issued">{{ issued | int if issued == (issued | int) else issued }}</span>
            </td>

            <td class="right">
                {% if remaining == 0 %}
                    <span class="badge badge-remaining-zero">0 ✓</span>
                {% elif remaining < row.qty %}
                    <span class="badge badge-remaining-some">{{ remaining | int if remaining == (remaining | int) else remaining }}</span>
                {% else %}
                    <span class="badge badge-remaining-full">{{ remaining | int if remaining == (remaining | int) else remaining }}</span>
                {% endif %}
            </td>

            <td class="center">{{ row.uom or row.stock_uom }}</td>

        </tr>
        {% endfor %}
    </tbody>
</table>

<!-- ═══════════════════════════════════════════════════════════
     TOTALS + ISSUANCE SUMMARY
════════════════════════════════════════════════════════════ -->
<table class="totals-strip">
<tr>

    <!-- LEFT — Issuance Summary -->
    <td class="totals-left">
        <div class="section-heading" style="margin-top:0; border-radius:2px;">ISSUANCE SUMMARY</div>
        <div class="issuance-box">

            {% set total_ordered = namespace(v=0) %}
            {% set total_issued = namespace(v=0) %}
            {% set total_remaining = namespace(v=0) %}

            {% for row in doc.items %}
                {% set total_ordered.v = total_ordered.v + (row.qty or 0) %}
                {% set total_issued.v = total_issued.v + (row.custom_issued_qty or 0) %}
                {% set total_remaining.v = total_remaining.v + (row.custom_remaining_qty or (row.qty - (row.custom_issued_qty or 0))) %}
            {% endfor %}

            <div class="issuance-row">
                <span class="issuance-label">Total Items</span>
                <span>{{ doc.items | length }}</span>
            </div>

            <div class="issuance-row">
                <span class="issuance-label">Total Qty Ordered</span>
                <span><b>{{ total_ordered.v | int if total_ordered.v == (total_ordered.v | int) else total_ordered.v }}</b></span>
            </div>

            <div class="issuance-row">
                <span class="issuance-label">Total Qty Issued</span>
                <span style="color:#155724; font-weight:700;">{{ total_issued.v | int if total_issued.v == (total_issued.v | int) else total_issued.v }}</span>
            </div>

            <div class="issuance-row">
                <span class="issuance-label">Total Qty Remaining</span>
                <span style="color:{% if total_remaining.v == 0 %}#155724{% else %}#856404{% endif %}; font-weight:700;">
                    {{ total_remaining.v | int if total_remaining.v == (total_remaining.v | int) else total_remaining.v }}
                    {% if total_remaining.v == 0 %} ✓ Fully Issued{% endif %}
                </span>
            </div>

        </div>
    </td>

    <!-- RIGHT — Totals -->
    <td class="totals-right">
        <div style="border: 1px solid #c5d3e8; border-radius: 2px; padding: 8px 10px; background:#f5f8ff;">

            <div class="total-line">
                <span>Total Qty</span>
                <span><b>{{ doc.total_qty }}</b></span>
            </div>

            {% if doc.total_amount %}
            <div class="total-line">
                <span>Total Amount</span>
                <span><b>{{ frappe.utils.fmt_money(doc.total_amount, currency=doc.currency) }}</b></span>
            </div>
            {% endif %}

            {% if doc.total_in_words %}
            <div style="margin-top:5px; color:#555; font-size:10px;">
                <i>{{ doc.total_in_words }}</i>
            </div>
            {% endif %}

        </div>
    </td>

</tr>
</table>

<!-- ═══════════════════════════════════════════════════════════
     LEGEND
════════════════════════════════════════════════════════════ -->
<div style="margin-top:10px; font-size:10px; color:#555; border-top: 1px dashed #c5d3e8; padding-top:6px;">
    <b style="color:#0a2351;">Legend:</b> &nbsp;
    <span class="badge badge-ordered">Ordered</span> &nbsp;
    <span class="badge badge-issued">Issued</span> &nbsp;
    <span class="badge badge-remaining-zero">Fully Issued ✓</span> &nbsp;
    <span class="badge badge-remaining-some">Partially Remaining</span> &nbsp;
    <span class="badge badge-remaining-full">Not Yet Issued</span>
</div>

<!-- ═══════════════════════════════════════════════════════════
     FOOTER — REQUESTED BY
════════════════════════════════════════════════════════════ -->
{% set owner_user = frappe.get_doc("User", doc.owner) %}
{% set emp = frappe.get_all("Employee",
    filters={"user_id": doc.owner},
    fields=["employee_name", "designation"],
    limit=1
) %}
{% set emp = emp[0] if emp else None %}

<div style="text-align:center; margin-top:50px; font-size:11px; color:#1a1a2e;">
    <div style="font-weight:700; font-size:12px;">
        {{ emp.employee_name if emp else (owner_user.full_name or doc.owner.split("@")[0]) }}
    </div>
    {% if emp and emp.designation %}
    <div style="color:#555; margin-top:2px;">{{ emp.designation }}</div>
    {% endif %}
</div>

{%- from "templates/print_formats/standard_macros.html" import add_header -%}

<style>
    .table-bordered td.top-bottom {
        border-top: none !important;
        border-bottom: none !important;
    }
    .table-bordered td.right {
        border-right: none !important;
    }
    .table-bordered td.left {
        border-left: none !important;
    }
    .section-title {
        font-size: 13px;
        font-weight: bold;
        margin-bottom: 4px;
        color: #333;
    }
    .aging-1yr   { background-color: #fff9e6; }
    .aging-2to5  { background-color: #ffe8cc; }
    .aging-5plus { background-color: #ffd6d6; font-weight: bold; }
    .aging-legend {
        font-size: 11px;
        margin-bottom: 4px;
        color: #555;
    }
    .aging-legend span {
        display: inline-block;
        margin-right: 12px;
        padding: 1px 6px;
        border-radius: 3px;
    }
</style>

<div>
    {# ── Dynamic heading based on payment_type ── #}
    {% if doc.payment_type == "Receive" %}
        {%- set _ = doc.set("select_print_heading", _("Receiving Entry")) -%}
    {% else %}
        {%- set _ = doc.set("select_print_heading", _("Payment Entry")) -%}
    {% endif %}

    {% set gl = frappe.get_list(
        doctype="GL Entry",
        fields=["account", "party_type", "party", "party_name", "debit", "credit", "remarks", "voucher_type", "account_currency", "against_voucher_type", "against_voucher"],
        filters={"voucher_type": doc.doctype, "voucher_no": doc.name}
    ) %}

    {{ add_header(0, 1, doc, letter_head, no_letterhead, print_settings) }}

    <div class="row margin-bottom">
        <div class="col-xs-6">
            <table>
                <tr>
                    <td><strong>Voucher No: </strong></td>
                    <td>{{ doc.name }}</td>
                </tr>
                <tr>
                    <td><strong>Type: </strong></td>
                    <td>{{ doc.payment_type }}
                    {% if doc.mode_of_payment %}
                    - {{ doc.mode_of_payment }}
                    {% endif %}
                    </td>
                </tr>
            </table>
        </div>

        <div class="col-xs-6">
            <table>
                <tr>
                    <td><strong>Date: </strong></td>
                    <td>{{ frappe.utils.format_date(doc.creation) }}</td>
                </tr>
                {% if doc.party %}
                <tr>
                    <td><strong>Party: </strong></td>
                    <td>
                        {{ doc.party_name }}<br>
                        <small>{{ doc.party_type }}/{{ doc.party }}</small>
                    </td>
                </tr>
                {% endif %}
            </table>
        </div>
    </div>

    {# ══════════════════════════════════════════════ #}
    {# ── GL Entry Table (current voucher) ── #}
    {# ══════════════════════════════════════════════ #}
    <div class="margin-top">
        <table class="table table-bordered table-condensed">
            <tr>
                <th>Account</th>
                <th width="184px">Party</th>
                <th width="104px">Amount</th>
            </tr>

            {% for entries in gl %}
                {% if entries.debit > 0 %}
                <tr>
                    <td class="right top-bottom">
                        {{ entries.account }}<br>
                        <small>
                        {% if entries.against_voucher_type %}
                            <strong>Voucher Type:</strong>: {{ entries.against_voucher_type }}<br>
                        {% endif %}
                        {% if entries.against_voucher %}
                            <strong>Voucher#:</strong>: {{ entries.against_voucher }}<br>
                        {% endif %}
                        {% if doc.paid_to == entries.account %}
                            <strong>Balance</strong>: {{ frappe.format(doc.paid_to_account_balance, {"fieldtype": "Currency"}) }}<br>
                        {% endif %}
                        {% if doc.project %}
                            <strong>Project</strong><br>{{ doc.project }}: {{ frappe.db.get_value("Project", doc.project, "project_name") }}<br>
                        {% endif %}
                        {% if doc.custom_project_uin %}
                            <strong>Project UIN</strong><br>
                            {{ doc.custom_project_uin }}<br>
                        {% endif %}
                        <strong>Narration</strong>: {{ entries.remarks }}
                        </small>
                    </td>
                    <td class="right left top-bottom">
                        {% if entries.party_type == "Employee" %}
                            {{ frappe.db.get_value("Employee", entries.party, "employee_name") or "" }}<br>
                        {% elif entries.party_type == "Customer" %}
                            {{ frappe.db.get_value("Customer", entries.party, "customer_name") or "" }}<br>
                        {% elif entries.party_type == "Supplier" %}
                            {{ frappe.db.get_value("Supplier", entries.party, "supplier_name") or "" }}<br>
                        {% endif %}
                        <span style="font-size: 75%; display: block; text-align: left;">
                            {{ entries.party or "" }}
                        </span>
                    </td>
                    <td class="left top-bottom text-right">{{ frappe.format(entries.debit, {"fieldtype": "Currency"}) }}</td>
                </tr>
                {% endif %}
            {% endfor %}

            <tr>
                <td class="right" colspan="2"><strong>Total (debit)</strong></td>
                <td class="left text-right">{{ frappe.format((gl | sum(attribute="debit")), {"fieldtype": "Currency"}) }}</td>
            </tr>

            {% for entries in gl %}
                {% if entries.credit > 0 %}
                <tr>
                    <td class="right top-bottom">
                        {{ entries.account }}<br>
                        <small>
                        {% if entries.against_voucher_type %}
                            <strong>Voucher Type:</strong>: {{ entries.against_voucher_type }}<br>
                        {% endif %}
                        {% if entries.against_voucher %}
                            <strong>Voucher#:</strong>: {{ entries.against_voucher }}<br>
                        {% endif %}
                        {% if doc.paid_from == entries.account %}
                            <strong>Balance</strong>: {{ frappe.format(doc.paid_from_account_balance, {"fieldtype": "Currency"}) }}<br>
                        {% endif %}
                        {% if doc.project %}
                            <strong>Project</strong><br>{{ doc.project }}: {{ frappe.db.get_value("Project", doc.project, "project_name") }}
                        {% endif %}
                        {% if doc.custom_project_uin %}
                            <strong>Project UIN</strong><br>
                            {{ doc.custom_project_uin }}<br>
                        {% endif %}
                        <strong>Narration</strong>: {{ entries.remarks }}
                        </small>
                    </td>
                    <td class="right left top-bottom">{{ entries.party or "" }}</td>
                    <td class="left top-bottom text-right">{{ frappe.format(entries.credit, {"fieldtype": "Currency"}) }}</td>
                </tr>
                {% endif %}
            {% endfor %}

            <tr>
                <td class="right" colspan="2"><strong>Total (credit)</strong></td>
                <td class="left text-right">{{ frappe.format((gl | sum(attribute="credit")), {"fieldtype": "Currency"}) }}</td>
            </tr>
        </table>
    </div>

    {# ══════════════════════════════════════════════════════════════════════════ #}
    {# ── Allocated Sales Invoices — only for Receipt Voucher (Customer) ── #}
    {# ══════════════════════════════════════════════════════════════════════════ #}
    {% if doc.payment_type == "Receive" and doc.references and doc.references|length > 0 %}
        {% set has_si = [] %}
        {% for ref in doc.references %}
            {% if ref.reference_doctype == "Sales Invoice" %}
                {% set _ = has_si.append(1) %}
            {% endif %}
        {% endfor %}

        {% if has_si|length > 0 %}
        <div class="margin-top">
            <table class="table table-bordered table-condensed">
                <tr>
                    <th>Invoice No</th>
                    <th>Description</th>
                    <th width="104px">Allocated Amount</th>
                </tr>

                {% for ref in doc.references %}
                {% if ref.reference_doctype == "Sales Invoice" %}

                    {% set inv = frappe.get_doc("Sales Invoice", ref.reference_name) if ref.reference_name else None %}
                    {% set item_desc = "—" %}

                    {% if inv and inv.items and inv.items|length > 0 %}
                        {% for item in inv.items %}
                            {% if item_desc == "—" and item.description and item.description.strip() %}
                                {% set raw_desc = item.description | trim | replace('\r\n', '\n') %}
                                {% set lines = raw_desc.split('\n') %}
                                {% set cleaned = [] %}
                                {% for line in lines %}
                                    {% if line.strip() %}
                                        {% set cleaned = cleaned + [line | trim] %}
                                    {% endif %}
                                {% endfor %}
                                {% set item_desc = cleaned | join(' ') if cleaned else item.item_name %}
                            {% endif %}
                        {% endfor %}
                        {% if item_desc == "—" %}
                            {% set item_desc = inv.items[0].item_name or "—" %}
                        {% endif %}
                    {% endif %}

                    <tr>
                        <td class="right top-bottom">{{ ref.reference_name }}</td>
                        <td class="right left top-bottom">{{ item_desc }}</td>
                        <td class="left top-bottom text-right">{{ frappe.format(ref.allocated_amount, {"fieldtype": "Currency"}) }}</td>
                    </tr>

                {% endif %}
                {% endfor %}
            </table>
        </div>
        {% endif %}
    {% endif %}
    {# ── End Allocated Sales Invoices ── #}


    {# ══════════════════════════════════════════════ #}
    {# ── Reference / Footer (moved above advances & aging) ── #}
    {# ══════════════════════════════════════════════ #}
    <table class="margin-top">
        <tr>
            <td>Reference No:</td>
            <td>{{ doc.reference_no or "-" }}</td>
        </tr>
        <tr>
            <td>Reference Date:</td>
            <td>{{ doc.reference_date or "-" }}</td>
        </tr>
        <tr>
            <td>Amount in Words:</td>
            <td>{{ doc.get_formatted("base_in_words") }}</td>
        </tr>
    </table>


    {# ══════════════════════════════════════════════════════════════════════════ #}
    {#                                                                            #}
    {#  PAY (Supplier or Employee) → Outstanding Advance Balances from GL        #}
    {#                                                                            #}
    {#  - Groups all GL rows for this party by account head                      #}
    {#  - Net = SUM(debit) - SUM(credit) per account                             #}
    {#  - Excludes the two staff loan/advance accounts by exact name             #}
    {#  - Only shows accounts where net balance != 0                             #}
    {#                                                                            #}
    {# ══════════════════════════════════════════════════════════════════════════ #}
    {% if doc.payment_type == "Pay" and doc.party_type in ("Supplier", "Employee") and doc.party %}

        {% set advances = frappe.db.sql("""
            SELECT
                gle.account,
                SUM(gle.debit - gle.credit) AS net_balance
            FROM `tabGL Entry` gle
            WHERE gle.party_type = %s
              AND gle.party = %s
              AND gle.is_cancelled = 0
              AND gle.account NOT IN (
                  '03-02-03-02-01 - Adv. to Staff Against Salaries - AKA',
                  '03-02-03-01-01 - Loan to Staff - AKA'
              )
            GROUP BY gle.account
            HAVING ABS(net_balance) > 0
            ORDER BY gle.account ASC
        """, (doc.party_type, doc.party,), as_dict=1) %}

        {% if advances %}
        <div class="margin-top">
            <p class="section-title">Outstanding Advance Balances — {{ doc.party_name }}</p>
            <table class="table table-bordered table-condensed">
                <tr>
                    <th>Account Head</th>
                    <th width="150px" class="text-right">Net Balance</th>
                </tr>
                {% set adv_total = namespace(v=0) %}
                {% for row in advances %}
                <tr>
                    <td>{{ row.account }}</td>
                    <td class="text-right">{{ frappe.format(row.net_balance, {"fieldtype": "Currency"}) }}</td>
                </tr>
                {% set adv_total.v = adv_total.v + row.net_balance %}
                {% endfor %}
                <tr>
                    <td><strong>Total Outstanding</strong></td>
                    <td class="text-right"><strong>{{ frappe.format(adv_total.v, {"fieldtype": "Currency"}) }}</strong></td>
                </tr>
            </table>
        </div>
        {% endif %}

    {% endif %}
    {# ── End Outstanding Advances (Pay / Supplier or Employee) ── #}


    {# ══════════════════════════════════════════════════════════════════════════ #}
    {#                                                                            #}
    {#  RECEIVE (Customer) → Receivable Aging bucketed by age from posting_date  #}
    {#                                                                            #}
    {#  Buckets (measured in days from posting_date to today):                   #}
    {#    ≤ 365  days  → Up to 1 Year                                            #}
    {#    366–1825     → 2 to 5 Years                                            #}
    {#    > 1825 days  → 5+ Years                                                #}
    {#                                                                            #}
    {#  Shows: summary bucket table + full invoice detail with color coding      #}
    {#                                                                            #}
    {# ══════════════════════════════════════════════════════════════════════════ #}
    {% if doc.payment_type == "Receive" and doc.party_type == "Customer" and doc.party %}

        {% set today = frappe.utils.today() %}

        {% set receivables = frappe.db.sql("""
            SELECT
                name,
                posting_date,
                outstanding_amount,
                DATEDIFF(%s, posting_date) AS age_days
            FROM `tabSales Invoice`
            WHERE customer = %s
              AND docstatus = 1
              AND outstanding_amount > 0
            ORDER BY posting_date ASC
        """, (today, doc.party), as_dict=1) %}

        {% if receivables %}

        {# ── Bucket invoices by age ── #}
        {% set bucket_1yr   = [] %}
        {% set bucket_2to5  = [] %}
        {% set bucket_5plus = [] %}
        {% for inv in receivables %}
            {% if inv.age_days <= 365 %}
                {% set _ = bucket_1yr.append(inv) %}
            {% elif inv.age_days <= 1825 %}
                {% set _ = bucket_2to5.append(inv) %}
            {% else %}
                {% set _ = bucket_5plus.append(inv) %}
            {% endif %}
        {% endfor %}

        {# ── Bucket totals using namespace (Jinja2 scope-safe) ── #}
        {% set t1   = namespace(v=0) %}
        {% set t2   = namespace(v=0) %}
        {% set t5   = namespace(v=0) %}
        {% for inv in bucket_1yr   %} {% set t1.v  = t1.v  + inv.outstanding_amount %} {% endfor %}
        {% for inv in bucket_2to5  %} {% set t2.v  = t2.v  + inv.outstanding_amount %} {% endfor %}
        {% for inv in bucket_5plus %} {% set t5.v  = t5.v  + inv.outstanding_amount %} {% endfor %}
        {% set grand_total = t1.v + t2.v + t5.v %}

        <div class="margin-top">
            <p class="section-title">Receivable Aging — {{ doc.party_name }}</p>

            <div class="aging-legend">
                <span class="aging-1yr">■ Up to 1 Year</span>
                <span class="aging-2to5">■ 2 – 5 Years</span>
                <span class="aging-5plus">■ 5+ Years</span>
            </div>

            {# ── Bucket Summary ── #}
            <table class="table table-bordered table-condensed">
                <tr>
                    <th>Age Bucket</th>
                    <th width="70px" class="text-right"># Invoices</th>
                    <th width="150px" class="text-right">Outstanding</th>
                </tr>
                {% if bucket_1yr %}
                <tr class="aging-1yr">
                    <td>Up to 1 Year</td>
                    <td class="text-right">{{ bucket_1yr | length }}</td>
                    <td class="text-right">{{ frappe.format(t1.v, {"fieldtype": "Currency"}) }}</td>
                </tr>
                {% endif %}
                {% if bucket_2to5 %}
                <tr class="aging-2to5">
                    <td>2 – 5 Years</td>
                    <td class="text-right">{{ bucket_2to5 | length }}</td>
                    <td class="text-right">{{ frappe.format(t2.v, {"fieldtype": "Currency"}) }}</td>
                </tr>
                {% endif %}
                {% if bucket_5plus %}
                <tr class="aging-5plus">
                    <td>5+ Years</td>
                    <td class="text-right">{{ bucket_5plus | length }}</td>
                    <td class="text-right">{{ frappe.format(t5.v, {"fieldtype": "Currency"}) }}</td>
                </tr>
                {% endif %}
                <tr>
                    <td colspan="2"><strong>Grand Total Outstanding</strong></td>
                    <td class="text-right"><strong>{{ frappe.format(grand_total, {"fieldtype": "Currency"}) }}</strong></td>
                </tr>
            </table>

        </div>
        {% endif %}

    {% endif %}
    {# ── End Receivable Aging (Receive / Customer) ── #}


    {# ══════════════════════════════════════════════ #}
    {# ── Signature Footer ── #}
    {# ══════════════════════════════════════════════ #}
    <table style="width:100%; border-collapse:separate; border-spacing:0; margin-top:40px; border:none;">
        <tr>
            <td style="text-align:left; border:none;">
                {{ frappe.db.get_value("User", doc.owner, "full_name") }}
            </td>
            <td style="text-align:center; border:none;">
                CFO
            </td>
            <td style="text-align:right; border:none;">
                <!-- Approved By name if needed -->
            </td>
        </tr>
        <tr>
            <td style="text-align:left; border:none;">
                <div style="border-top:1px solid black; padding-top:8px; display:inline-block; text-align:center; min-width:150px;">
                    Prepared By
                </div>
            </td>
            <td style="text-align:center; border:none;">
                <div style="border-top:1px solid black; padding-top:8px; display:inline-block; min-width:150px;">
                    Checked By
                </div>
            </td>
            <td style="text-align:right; border:none;">
                <div style="border-top:1px solid black; padding-top:8px; display:inline-block; text-align:center; min-width:150px;">
                    Approved By
                </div>
            </td>
        </tr>
    </table>
</div>

{%- from "templates/print_formats/standard_macros.html" import add_header -%}

<style>
    .table-bordered td.top-bottom {
        border-top: none !important;
        border-bottom: none !important;
    }
    .table-bordered td.right {
        border-right: none !important;
    }
    .table-bordered td.left {
        border-left: none !important;
    }
    .section-title {
        font-size: 13px;
        font-weight: bold;
        margin-bottom: 4px;
        color: #333;
    }
    .aging-1yr   { background-color: #fff9e6; }
    .aging-2to5  { background-color: #ffe8cc; }
    .aging-5plus { background-color: #ffd6d6; font-weight: bold; }
    .aging-legend {
        font-size: 11px;
        margin-bottom: 4px;
        color: #555;
    }
    .aging-legend span {
        display: inline-block;
        margin-right: 12px;
        padding: 1px 6px;
        border-radius: 3px;
    }
</style>

<div>
    {# ── Dynamic heading based on payment_type ── #}
    {% if doc.payment_type == "Receive" %}
        {%- set _ = doc.set("select_print_heading", _("Receiving Entry")) -%}
    {% else %}
        {%- set _ = doc.set("select_print_heading", _("Payment Entry")) -%}
    {% endif %}

    {% set gl = frappe.get_list(
        doctype="GL Entry",
        fields=["account", "party_type", "party", "party_name", "debit", "credit", "debit_in_account_currency", "credit_in_account_currency", "remarks", "voucher_type", "account_currency", "against_voucher_type", "against_voucher"],
        filters={"voucher_type": doc.doctype, "voucher_no": doc.name}
    ) %}

    {# currency used for totals (document currency) #}
    {% set doc_currency = doc.paid_to_account_currency if doc.payment_type == "Receive" else doc.paid_from_account_currency %}

    {{ add_header(0, 1, doc, letter_head, no_letterhead, print_settings) }}

    <div class="row margin-bottom">
        <div class="col-xs-6">
            <table>
                <tr>
                    <td><strong>Voucher No: </strong></td>
                    <td>{{ doc.name }}</td>
                </tr>
                <tr>
                    <td><strong>Type: </strong></td>
                    <td>{{ doc.payment_type }}
                    {% if doc.mode_of_payment %}
                    - {{ doc.mode_of_payment }}
                    {% endif %}
                    </td>
                </tr>
            </table>
        </div>

        <div class="col-xs-6">
            <table>
                <tr>
                    <td><strong>Date: </strong></td>
                    <td>{{ frappe.utils.format_date(doc.creation) }}</td>
                </tr>
                {% if doc.party %}
                <tr>
                    <td><strong>Party: </strong></td>
                    <td>
                        {{ doc.party_name }}<br>
                        <small>{{ doc.party_type }}/{{ doc.party }}</small>
                    </td>
                </tr>
                {% endif %}
            </table>
        </div>
    </div>

    {# ══════════════════════════════════════════════ #}
    {# ── GL Entry Table (current voucher) ── #}
    {# ══════════════════════════════════════════════ #}
    <div class="margin-top">
        <table class="table table-bordered table-condensed">
            <tr>
                <th>Account</th>
                <th width="184px">Party</th>
                <th width="104px">Amount</th>
            </tr>

            {% for entries in gl %}
                {% if entries.debit > 0 %}
                <tr>
                    <td class="right top-bottom">
                        {{ entries.account }}<br>
                        <small>
                        {% if entries.against_voucher_type %}
                            <strong>Voucher Type:</strong>: {{ entries.against_voucher_type }}<br>
                        {% endif %}
                        {% if entries.against_voucher %}
                            <strong>Voucher#:</strong>: {{ entries.against_voucher }}<br>
                        {% endif %}
                        {% if doc.paid_to == entries.account %}
                            <strong>Balance</strong>: {{ frappe.format(doc.paid_to_account_balance, {"fieldtype": "Currency"}, currency=doc.paid_to_account_currency) }}<br>
                        {% endif %}
                        {% if doc.project %}
                            <strong>Project</strong><br>{{ doc.project }}: {{ frappe.db.get_value("Project", doc.project, "project_name") }}<br>
                        {% endif %}
                        {% if doc.custom_project_uin %}
                            <strong>Project UIN</strong><br>
                            {{ doc.custom_project_uin }}<br>
                        {% endif %}
                        <strong>Narration</strong>: {{ entries.remarks }}
                        </small>
                    </td>
                    <td class="right left top-bottom">
                        {% if entries.party_type == "Employee" %}
                            {{ frappe.db.get_value("Employee", entries.party, "employee_name") or "" }}<br>
                        {% elif entries.party_type == "Customer" %}
                            {{ frappe.db.get_value("Customer", entries.party, "customer_name") or "" }}<br>
                        {% elif entries.party_type == "Supplier" %}
                            {{ frappe.db.get_value("Supplier", entries.party, "supplier_name") or "" }}<br>
                        {% endif %}
                        <span style="font-size: 75%; display: block; text-align: left;">
                            {{ entries.party or "" }}
                        </span>
                    </td>
                    <td class="left top-bottom text-right">{{ frappe.format(entries.debit_in_account_currency, {"fieldtype": "Currency"}, currency=entries.account_currency) }}</td>
                </tr>
                {% endif %}
            {% endfor %}

            <tr>
                <td class="right" colspan="2"><strong>Total (debit)</strong></td>
                <td class="left text-right">{{ frappe.format((gl | sum(attribute="debit_in_account_currency")), {"fieldtype": "Currency"}, currency=doc_currency) }}</td>
            </tr>

            {% for entries in gl %}
                {% if entries.credit > 0 %}
                <tr>
                    <td class="right top-bottom">
                        {{ entries.account }}<br>
                        <small>
                        {% if entries.against_voucher_type %}
                            <strong>Voucher Type:</strong>: {{ entries.against_voucher_type }}<br>
                        {% endif %}
                        {% if entries.against_voucher %}
                            <strong>Voucher#:</strong>: {{ entries.against_voucher }}<br>
                        {% endif %}
                        {% if doc.paid_from == entries.account %}
                            <strong>Balance</strong>: {{ frappe.format(doc.paid_from_account_balance, {"fieldtype": "Currency"}, currency=doc.paid_from_account_currency) }}<br>
                        {% endif %}
                        {% if doc.project %}
                            <strong>Project</strong><br>{{ doc.project }}: {{ frappe.db.get_value("Project", doc.project, "project_name") }}
                        {% endif %}
                        {% if doc.custom_project_uin %}
                            <strong>Project UIN</strong><br>
                            {{ doc.custom_project_uin }}<br>
                        {% endif %}
                        <strong>Narration</strong>: {{ entries.remarks }}
                        </small>
                    </td>
                    <td class="right left top-bottom">{{ entries.party or "" }}</td>
                    <td class="left top-bottom text-right">{{ frappe.format(entries.credit_in_account_currency, {"fieldtype": "Currency"}, currency=entries.account_currency) }}</td>
                </tr>
                {% endif %}
            {% endfor %}

            <tr>
                <td class="right" colspan="2"><strong>Total (credit)</strong></td>
                <td class="left text-right">{{ frappe.format((gl | sum(attribute="credit_in_account_currency")), {"fieldtype": "Currency"}, currency=doc_currency) }}</td>
            </tr>
        </table>
    </div>

    {# ══════════════════════════════════════════════════════════════════════════ #}
    {# ── Allocated Sales Invoices — only for Receipt Voucher (Customer) ── #}
    {# ══════════════════════════════════════════════════════════════════════════ #}
    {% if doc.payment_type == "Receive" and doc.references and doc.references|length > 0 %}
        {% set has_si = [] %}
        {% for ref in doc.references %}
            {% if ref.reference_doctype == "Sales Invoice" %}
                {% set _ = has_si.append(1) %}
            {% endif %}
        {% endfor %}

        {% if has_si|length > 0 %}
        <div class="margin-top">
            <table class="table table-bordered table-condensed">
                <tr>
                    <th>Invoice No</th>
                    <th>Description</th>
                    <th width="104px">Allocated Amount</th>
                </tr>

                {% for ref in doc.references %}
                {% if ref.reference_doctype == "Sales Invoice" %}

                    {% set inv = frappe.get_doc("Sales Invoice", ref.reference_name) if ref.reference_name else None %}
                    {% set item_desc = "—" %}

                    {% if inv and inv.items and inv.items|length > 0 %}
                        {% for item in inv.items %}
                            {% if item_desc == "—" and item.description and item.description.strip() %}
                                {% set raw_desc = item.description | trim | replace('\r\n', '\n') %}
                                {% set lines = raw_desc.split('\n') %}
                                {% set cleaned = [] %}
                                {% for line in lines %}
                                    {% if line.strip() %}
                                        {% set cleaned = cleaned + [line | trim] %}
                                    {% endif %}
                                {% endfor %}
                                {% set item_desc = cleaned | join(' ') if cleaned else item.item_name %}
                            {% endif %}
                        {% endfor %}
                        {% if item_desc == "—" %}
                            {% set item_desc = inv.items[0].item_name or "—" %}
                        {% endif %}
                    {% endif %}

                    <tr>
                        <td class="right top-bottom">{{ ref.reference_name }}</td>
                        <td class="right left top-bottom">{{ item_desc }}</td>
                        <td class="left top-bottom text-right">{{ frappe.format(ref.allocated_amount, {"fieldtype": "Currency"}, currency=doc.paid_from_account_currency) }}</td>
                    </tr>

                {% endif %}
                {% endfor %}
            </table>
        </div>
        {% endif %}
    {% endif %}
    {# ── End Allocated Sales Invoices ── #}


    {# ══════════════════════════════════════════════ #}
    {# ── Reference / Footer (moved above advances & aging) ── #}
    {# ══════════════════════════════════════════════ #}
    <table class="margin-top">
        <tr>
            <td>Reference No:</td>
            <td>{{ doc.reference_no or "-" }}</td>
        </tr>
        <tr>
            <td>Reference Date:</td>
            <td>{{ doc.reference_date or "-" }}</td>
        </tr>
        {# ============================================================
           INTERNATIONAL AMOUNT IN WORDS
           Never uses Lakh / Crore.
           Uses Thousand / Million / Billion / Trillion.
           Currency comes from the Payment Entry document.
           ============================================================ #}
        
        {% macro international_words(n) -%}
            {% set ones = [
                "Zero", "One", "Two", "Three", "Four",
                "Five", "Six", "Seven", "Eight", "Nine",
                "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen",
                "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"
            ] %}
        
            {% set tens = [
                "", "", "Twenty", "Thirty", "Forty",
                "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"
            ] %}
        
            {% if n < 20 %}
                {{ ones[n] }}
        
            {% elif n < 100 %}
                {{ tens[n // 10] }}
                {% if n % 10 %}
                    {{ international_words(n % 10) }}
                {% endif %}
        
            {% elif n < 1000 %}
                {{ international_words(n // 100) }} Hundred
                {% if n % 100 %}
                    {{ international_words(n % 100) }}
                {% endif %}
        
            {% elif n < 1000000 %}
                {{ international_words(n // 1000) }} Thousand
                {% if n % 1000 %}
                    {{ international_words(n % 1000) }}
                {% endif %}
        
            {% elif n < 1000000000 %}
                {{ international_words(n // 1000000) }} Million
                {% if n % 1000000 %}
                    {{ international_words(n % 1000000) }}
                {% endif %}
        
            {% elif n < 1000000000000 %}
                {{ international_words(n // 1000000000) }} Billion
                {% if n % 1000000000 %}
                    {{ international_words(n % 1000000000) }}
                {% endif %}
        
            {% else %}
                {{ international_words(n // 1000000000000) }} Trillion
                {% if n % 1000000000000 %}
                    {{ international_words(n % 1000000000000) }}
                {% endif %}
            {% endif %}
        {%- endmacro %}
        
        {% if doc.payment_type == "Pay" %}
            {% set amount_for_words = doc.base_paid_amount or 0 %}
        {% else %}
            {% set amount_for_words = doc.base_received_amount or 0 %}
        {% endif %}
        
        {% set amount_for_words = amount_for_words | round(0) | int %}
        {% set words_currency = doc.company_currency or "Currency" %}
        
        <tr>
            <td>Amount in Words:</td>
            <td>
                    {{ words_currency }}
                    {{ international_words(amount_for_words) }}
                    Only
            </td>
        </tr>
    </table>


    {# ══════════════════════════════════════════════════════════════════════════ #}
    {#                                                                            #}
    {#  PAY (Supplier or Employee) → Outstanding Advance Balances from GL        #}
    {#                                                                            #}
    {#  - Resolves each GL row's account to its immediate parent_account in the  #}
    {#    real Chart of Accounts tree (falls back to the account itself if it    #}
    {#    has no parent), then groups/sums by that parent                        #}
    {#  - Net = SUM(debit) - SUM(credit) per parent account group                #}
    {#  - Excludes the two staff loan/advance accounts by exact name             #}
    {#    (excluded before aggregation, at the leaf-account level)               #}
    {#  - Only shows groups where net balance != 0                               #}
    {#                                                                            #}
    {# ══════════════════════════════════════════════════════════════════════════ #}
    {% if doc.payment_type == "Pay" and doc.party_type in ("Supplier", "Employee") and doc.party %}

        {% set advances = frappe.db.sql("""
            SELECT
                COALESCE(acc.parent_account, gle.account) AS account,
                SUM(gle.debit - gle.credit) AS net_balance
            FROM `tabGL Entry` gle
            LEFT JOIN `tabAccount` acc
                ON acc.name = gle.account
            WHERE gle.party_type = %s
              AND gle.party = %s
              AND gle.is_cancelled = 0
              AND gle.account NOT IN (
                  '03-02-03-02-01 - Adv. to Staff Against Salaries - RM',
                  '03-02-03-01-01 - Loan to Staff - RM'
              )
            GROUP BY COALESCE(acc.parent_account, gle.account)
            HAVING ABS(net_balance) > 0
            ORDER BY account ASC
        """, (doc.party_type, doc.party,), as_dict=1) %}

        {% if advances %}
        <div class="margin-top">
            <p class="section-title">Outstanding Advance Balances — {{ doc.party_name }}</p>
            <table class="table table-bordered table-condensed">
                <tr>
                    <th>Account Head</th>
                    <th width="150px" class="text-right">Net Balance</th>
                </tr>
                {% set adv_total = namespace(v=0) %}
                {% for row in advances %}
                <tr>
                    <td>{{ row.account }}</td>
                    <td class="text-right">{{ frappe.format(row.net_balance, {"fieldtype": "Currency"}) }}</td>
                </tr>
                {% set adv_total.v = adv_total.v + row.net_balance %}
                {% endfor %}
                <tr>
                    <td><strong>Total Outstanding</strong></td>
                    <td class="text-right"><strong>{{ frappe.format(adv_total.v, {"fieldtype": "Currency"}) }}</strong></td>
                </tr>
            </table>
        </div>
        {% endif %}

    {% endif %}
    {# ── End Outstanding Advances (Pay / Supplier or Employee) ── #}


    {# ══════════════════════════════════════════════════════════════════════════ #}
    {#                                                                            #}
    {#  RECEIVE (Customer) → Receivable Aging bucketed by age from posting_date  #}
    {#                                                                            #}
    {#  Buckets (measured in days from posting_date to today):                   #}
    {#    ≤ 365  days  → Up to 1 Year                                            #}
    {#    366–1825     → 2 to 5 Years                                            #}
    {#    > 1825 days  → 5+ Years                                                #}
    {#                                                                            #}
    {#  Shows: summary bucket table + full invoice detail with color coding      #}
    {#                                                                            #}
    {# ══════════════════════════════════════════════════════════════════════════ #}
    {% if doc.payment_type == "Receive" and doc.party_type == "Customer" and doc.party %}

        {% set today = frappe.utils.today() %}

        {% set receivables = frappe.db.sql("""
            SELECT
                name,
                posting_date,
                outstanding_amount,
                DATEDIFF(%s, posting_date) AS age_days
            FROM `tabSales Invoice`
            WHERE customer = %s
              AND docstatus = 1
              AND outstanding_amount > 0
            ORDER BY posting_date ASC
        """, (today, doc.party), as_dict=1) %}

        {% if receivables %}

        {# ── Bucket invoices by age ── #}
        {% set bucket_1yr   = [] %}
        {% set bucket_2to5  = [] %}
        {% set bucket_5plus = [] %}
        {% for inv in receivables %}
            {% if inv.age_days <= 365 %}
                {% set _ = bucket_1yr.append(inv) %}
            {% elif inv.age_days <= 1825 %}
                {% set _ = bucket_2to5.append(inv) %}
            {% else %}
                {% set _ = bucket_5plus.append(inv) %}
            {% endif %}
        {% endfor %}

        {# ── Bucket totals using namespace (Jinja2 scope-safe) ── #}
        {% set t1   = namespace(v=0) %}
        {% set t2   = namespace(v=0) %}
        {% set t5   = namespace(v=0) %}
        {% for inv in bucket_1yr   %} {% set t1.v  = t1.v  + inv.outstanding_amount %} {% endfor %}
        {% for inv in bucket_2to5  %} {% set t2.v  = t2.v  + inv.outstanding_amount %} {% endfor %}
        {% for inv in bucket_5plus %} {% set t5.v  = t5.v  + inv.outstanding_amount %} {% endfor %}
        {% set grand_total = t1.v + t2.v + t5.v %}

        <div class="margin-top">
            <p class="section-title">Receivable Aging — {{ doc.party_name }}</p>

            <div class="aging-legend">
                <span class="aging-1yr">■ Up to 1 Year</span>
                <span class="aging-2to5">■ 2 – 5 Years</span>
                <span class="aging-5plus">■ 5+ Years</span>
            </div>

            {# ── Bucket Summary ── #}
            <table class="table table-bordered table-condensed">
                <tr>
                    <th>Age Bucket</th>
                    <th width="70px" class="text-right"># Invoices</th>
                    <th width="150px" class="text-right">Outstanding</th>
                </tr>
                {% if bucket_1yr %}
                <tr class="aging-1yr">
                    <td>Up to 1 Year</td>
                    <td class="text-right">{{ bucket_1yr | length }}</td>
                    <td class="text-right">{{ frappe.format(t1.v, {"fieldtype": "Currency"}) }}</td>
                </tr>
                {% endif %}
                {% if bucket_2to5 %}
                <tr class="aging-2to5">
                    <td>2 – 5 Years</td>
                    <td class="text-right">{{ bucket_2to5 | length }}</td>
                    <td class="text-right">{{ frappe.format(t2.v, {"fieldtype": "Currency"}) }}</td>
                </tr>
                {% endif %}
                {% if bucket_5plus %}
                <tr class="aging-5plus">
                    <td>5+ Years</td>
                    <td class="text-right">{{ bucket_5plus | length }}</td>
                    <td class="text-right">{{ frappe.format(t5.v, {"fieldtype": "Currency"}) }}</td>
                </tr>
                {% endif %}
                <tr>
                    <td colspan="2"><strong>Grand Total Outstanding</strong></td>
                    <td class="text-right"><strong>{{ frappe.format(grand_total, {"fieldtype": "Currency"}) }}</strong></td>
                </tr>
            </table>

        </div>
        {% endif %}

    {% endif %}
    {# ── End Receivable Aging (Receive / Customer) ── #}


    {# ══════════════════════════════════════════════ #}
    {# ── Signature Footer ── #}
    {# ══════════════════════════════════════════════ #}
    <table style="width:100%; border-collapse:separate; border-spacing:0; margin-top:40px; border:none;">
        <tr>
            <td style="text-align:left; border:none;">
                {{ frappe.db.get_value("User", doc.owner, "full_name") }}
            </td>
            <td style="text-align:center; border:none;">
                CFO
            </td>
            <td style="text-align:right; border:none;">
                <!-- Approved By name if needed -->
            </td>
        </tr>
        <tr>
            <td style="text-align:left; border:none;">
                <div style="border-top:1px solid black; padding-top:8px; display:inline-block; text-align:center; min-width:150px;">
                    Prepared By
                </div>
            </td>
            <td style="text-align:center; border:none;">
                <div style="border-top:1px solid black; padding-top:8px; display:inline-block; min-width:150px;">
                    Checked By
                </div>
            </td>
            <td style="text-align:right; border:none;">
                <div style="border-top:1px solid black; padding-top:8px; display:inline-block; text-align:center; min-width:150px;">
                    Approved By
                </div>
            </td>
        </tr>
    </table>
</div>

{%- from "templates/print_formats/standard_macros.html" import add_header -%}

<style>
    .table-bordered td.top-bottom {
        border-top: none !important;
        border-bottom: none !important;
    } <td>{{ doc.get_formatted("base_in_words") }}</td>
    .table-bordered td.right {
        border-right: none !important;
    }
    .table-bordered td.left {
        border-left: none !important;
    }
    .section-title {
        font-size: 13px;
        font-weight: bold;
        margin-bottom: 4px;
        color: #333;
    }
    .aging-1yr   { background-color: #fff9e6; }
    .aging-2to5  { background-color: #ffe8cc; }
    .aging-5plus { background-color: #ffd6d6; font-weight: bold; }
    .aging-legend {
        font-size: 11px;
        margin-bottom: 4px;
        color: #555;
    }
    .aging-legend span {
        display: inline-block;
        margin-right: 12px;
        padding: 1px 6px;
        border-radius: 3px;
    }
</style>

<div>
    {# ── Dynamic heading based on payment_type ── #}
    {% if doc.payment_type == "Receive" %}
        {%- set _ = doc.set("select_print_heading", _("Receiving Entry")) -%}
    {% else %}
        {%- set _ = doc.set("select_print_heading", _("Payment Entry")) -%}
    {% endif %}

    {% set gl = frappe.get_list(
        doctype="GL Entry",
        fields=["account", "party_type", "party", "party_name", "debit", "credit", "remarks", "voucher_type", "account_currency", "against_voucher_type", "against_voucher"],
        filters={"voucher_type": doc.doctype, "voucher_no": doc.name}
    ) %}

    {{ add_header(0, 1, doc, letter_head, no_letterhead, print_settings) }}

    <div class="row margin-bottom">
        <div class="col-xs-6">
            <table>
                <tr>
                    <td><strong>Voucher No: </strong></td>
                    <td>{{ doc.name }}</td>
                </tr>
                <tr>
                    <td><strong>Type: </strong></td>
                    <td>{{ doc.payment_type }}
                    {% if doc.mode_of_payment %}
                    - {{ doc.mode_of_payment }}
                    {% endif %}
                    </td>
                </tr>
            </table>
        </div>

        <div class="col-xs-6">
            <table>
                <tr>
                    <td><strong>Date: </strong></td>
                    <td>{{ frappe.utils.format_date(doc.creation) }}</td>
                </tr>
                {% if doc.party %}
                <tr>
                    <td><strong>Party: </strong></td>
                    <td>
                        {{ doc.party_name }}<br>
                        <small>{{ doc.party_type }}/{{ doc.party }}</small>
                    </td>
                </tr>
                {% endif %}
            </table>
        </div>
    </div>

    {# ══════════════════════════════════════════════ #}
    {# ── GL Entry Table (current voucher) ── #}
    {# ══════════════════════════════════════════════ #}
    <div class="margin-top">
        <table class="table table-bordered table-condensed">
            <tr>
                <th>Account</th>
                <th width="184px">Party</th>
                <th width="104px">Amount</th>
            </tr>

            {% for entries in gl %}
                {% if entries.debit > 0 %}
                <tr>
                    <td class="right top-bottom">
                        {{ entries.account }}<br>
                        <small>
                        {% if entries.against_voucher_type %}
                            <strong>Voucher Type:</strong>: {{ entries.against_voucher_type }}<br>
                        {% endif %}
                        {% if entries.against_voucher %}
                            <strong>Voucher#:</strong>: {{ entries.against_voucher }}<br>
                        {% endif %}
                        {% if doc.paid_to == entries.account %}
                            <strong>Balance</strong>: {{ frappe.format(doc.paid_to_account_balance, {"fieldtype": "Currency"}) }}<br>
                        {% endif %}
                        {% if doc.project %}
                            <strong>Project</strong><br>{{ doc.project }}: {{ frappe.db.get_value("Project", doc.project, "project_name") }}<br>
                        {% endif %}
                        {% if doc.custom_project_uin %}
                            <strong>Project UIN</strong><br>
                            {{ doc.custom_project_uin }}<br>
                        {% endif %}
                        <strong>Narration</strong>: {{ entries.remarks }}
                        </small>
                    </td>
                    <td class="right left top-bottom">
                        {% if entries.party_type == "Employee" %}
                            {{ frappe.db.get_value("Employee", entries.party, "employee_name") or "" }}<br>
                        {% elif entries.party_type == "Customer" %}
                            {{ frappe.db.get_value("Customer", entries.party, "customer_name") or "" }}<br>
                        {% elif entries.party_type == "Supplier" %}
                            {{ frappe.db.get_value("Supplier", entries.party, "supplier_name") or "" }}<br>
                        {% endif %}
                        <span style="font-size: 75%; display: block; text-align: left;">
                            {{ entries.party or "" }}
                        </span>
                    </td>
                    <td class="left top-bottom text-right">{{ frappe.format(entries.debit, {"fieldtype": "Currency"}) }}</td>
                </tr>
                {% endif %}
            {% endfor %}

            <tr>
                <td class="right" colspan="2"><strong>Total (debit)</strong></td>
                <td class="left text-right">{{ frappe.format((gl | sum(attribute="debit")), {"fieldtype": "Currency"}) }}</td>
            </tr>

            {% for entries in gl %}
                {% if entries.credit > 0 %}
                <tr>
                    <td class="right top-bottom">
                        {{ entries.account }}<br>
                        <small>
                        {% if entries.against_voucher_type %}
                            <strong>Voucher Type:</strong>: {{ entries.against_voucher_type }}<br>
                        {% endif %}
                        {% if entries.against_voucher %}
                            <strong>Voucher#:</strong>: {{ entries.against_voucher }}<br>
                        {% endif %}
                        {% if doc.paid_from == entries.account %}
                            <strong>Balance</strong>: {{ frappe.format(doc.paid_from_account_balance, {"fieldtype": "Currency"}) }}<br>
                        {% endif %}
                        {% if doc.project %}
                            <strong>Project</strong><br>{{ doc.project }}: {{ frappe.db.get_value("Project", doc.project, "project_name") }}
                        {% endif %}
                        {% if doc.custom_project_uin %}
                            <strong>Project UIN</strong><br>
                            {{ doc.custom_project_uin }}<br>
                        {% endif %}
                        <strong>Narration</strong>: {{ entries.remarks }}
                        </small>
                    </td>
                    <td class="right left top-bottom">{{ entries.party or "" }}</td>
                    <td class="left top-bottom text-right">{{ frappe.format(entries.credit, {"fieldtype": "Currency"}) }}</td>
                </tr>
                {% endif %}
            {% endfor %}

            <tr>
                <td class="right" colspan="2"><strong>Total (credit)</strong></td>
                <td class="left text-right">{{ frappe.format((gl | sum(attribute="credit")), {"fieldtype": "Currency"}) }}</td>
            </tr>
        </table>
    </div>

    {# ══════════════════════════════════════════════════════════════════════════ #}
    {# ── Allocated Sales Invoices — only for Receipt Voucher (Customer) ── #}
    {# ══════════════════════════════════════════════════════════════════════════ #}
    {% if doc.payment_type == "Receive" and doc.references and doc.references|length > 0 %}
        {% set has_si = [] %}
        {% for ref in doc.references %}
            {% if ref.reference_doctype == "Sales Invoice" %}
                {% set _ = has_si.append(1) %}
            {% endif %}
        {% endfor %}

        {% if has_si|length > 0 %}
        <div class="margin-top">
            <table class="table table-bordered table-condensed">
                <tr>
                    <th>Invoice No</th>
                    <th>Description</th>
                    <th width="104px">Allocated Amount</th>
                </tr>

                {% for ref in doc.references %}
                {% if ref.reference_doctype == "Sales Invoice" %}

                    {% set inv = frappe.get_doc("Sales Invoice", ref.reference_name) if ref.reference_name else None %}
                    {% set item_desc = "—" %}

                    {% if inv and inv.items and inv.items|length > 0 %}
                        {% for item in inv.items %}
                            {% if item_desc == "—" and item.description and item.description.strip() %}
                                {% set raw_desc = item.description | trim | replace('\r\n', '\n') %}
                                {% set lines = raw_desc.split('\n') %}
                                {% set cleaned = [] %}
                                {% for line in lines %}
                                    {% if line.strip() %}
                                        {% set cleaned = cleaned + [line | trim] %}
                                    {% endif %}
                                {% endfor %}
                                {% set item_desc = cleaned | join(' ') if cleaned else item.item_name %}
                            {% endif %}
                        {% endfor %}
                        {% if item_desc == "—" %}
                            {% set item_desc = inv.items[0].item_name or "—" %}
                        {% endif %}
                    {% endif %}

                    <tr>
                        <td class="right top-bottom">{{ ref.reference_name }}</td>
                        <td class="right left top-bottom">{{ item_desc }}</td>
                        <td class="left top-bottom text-right">{{ frappe.format(ref.allocated_amount, {"fieldtype": "Currency"}) }}</td>
                    </tr>

                {% endif %}
                {% endfor %}
            </table>
        </div>
        {% endif %}
    {% endif %}
    {# ── End Allocated Sales Invoices ── #}


    {# ══════════════════════════════════════════════ #}
    {# ── Reference / Footer (moved above advances & aging) ── #}
    {# ══════════════════════════════════════════════ #}
    <table class="margin-top">
        <tr>
            <td>Reference No:</td>
            <td>{{ doc.reference_no or "-" }}</td>
        </tr>
        <tr>
            <td>Reference Date:</td>
            <td>{{ doc.reference_date or "-" }}</td>
        </tr>
        {# ============================================================
           INTERNATIONAL AMOUNT IN WORDS
           Never uses Lakh / Crore.
           Uses Thousand / Million / Billion / Trillion.
           Currency comes from the Payment Entry document.
           ============================================================ #}
        
        {% macro international_words(n) -%}
            {% set ones = [
                "Zero", "One", "Two", "Three", "Four",
                "Five", "Six", "Seven", "Eight", "Nine",
                "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen",
                "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"
            ] %}
        
            {% set tens = [
                "", "", "Twenty", "Thirty", "Forty",
                "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"
            ] %}
        
            {% if n < 20 %}
                {{ ones[n] }}
        
            {% elif n < 100 %}
                {{ tens[n // 10] }}
                {% if n % 10 %}
                    {{ international_words(n % 10) }}
                {% endif %}
        
            {% elif n < 1000 %}
                {{ international_words(n // 100) }} Hundred
                {% if n % 100 %}
                    {{ international_words(n % 100) }}
                {% endif %}
        
            {% elif n < 1000000 %}
                {{ international_words(n // 1000) }} Thousand
                {% if n % 1000 %}
                    {{ international_words(n % 1000) }}
                {% endif %}
        
            {% elif n < 1000000000 %}
                {{ international_words(n // 1000000) }} Million
                {% if n % 1000000 %}
                    {{ international_words(n % 1000000) }}
                {% endif %}
        
            {% elif n < 1000000000000 %}
                {{ international_words(n // 1000000000) }} Billion
                {% if n % 1000000000 %}
                    {{ international_words(n % 1000000000) }}
                {% endif %}
        
            {% else %}
                {{ international_words(n // 1000000000000) }} Trillion
                {% if n % 1000000000000 %}
                    {{ international_words(n % 1000000000000) }}
                {% endif %}
            {% endif %}
        {%- endmacro %}
        
        {% if doc.payment_type == "Pay" %}
            {% set amount_for_words = doc.base_paid_amount or 0 %}
        {% else %}
            {% set amount_for_words = doc.base_received_amount or 0 %}
        {% endif %}
        
        {% set amount_for_words = amount_for_words | round(0) | int %}
        {% set words_currency = doc.company_currency or "Currency" %}
        
        <tr>
            <td>Amount in Words:</td>
            <td>
                    {{ words_currency }}
                    {{ international_words(amount_for_words) }}
                    Only
            </td>
        </tr>
    </table>


    {# ══════════════════════════════════════════════════════════════════════════ #}
    {#                                                                            #}
    {#  PAY (Supplier or Employee) → Outstanding Advance Balances from GL        #}
    {#                                                                            #}
    {#  - Resolves each GL row's account to its immediate parent_account in the  #}
    {#    real Chart of Accounts tree (falls back to the account itself if it    #}
    {#    has no parent), then groups/sums by that parent                        #}
    {#  - Net = SUM(debit) - SUM(credit) per parent account group                #}
    {#  - Excludes the two staff loan/advance accounts by exact name             #}
    {#    (excluded before aggregation, at the leaf-account level)               #}
    {#  - Only shows groups where net balance != 0                               #}
    {#                                                                            #}
    {# ══════════════════════════════════════════════════════════════════════════ #}
    {% if doc.payment_type == "Pay" and doc.party_type in ("Supplier", "Employee") and doc.party %}

        {% set advances = frappe.db.sql("""
            SELECT
                COALESCE(acc.parent_account, gle.account) AS account,
                SUM(gle.debit - gle.credit) AS net_balance
            FROM `tabGL Entry` gle
            LEFT JOIN `tabAccount` acc
                ON acc.name = gle.account
            WHERE gle.party_type = %s
              AND gle.party = %s
              AND gle.is_cancelled = 0
              AND gle.account NOT IN (
                  '03-02-03-02-01 - Adv. to Staff Against Salaries - RM',
                  '03-02-03-01-01 - Loan to Staff - RM'
              )
            GROUP BY COALESCE(acc.parent_account, gle.account)
            HAVING ABS(net_balance) > 0
            ORDER BY account ASC
        """, (doc.party_type, doc.party,), as_dict=1) %}

        {% if advances %}
        <div class="margin-top">
            <p class="section-title">Outstanding Advance Balances — {{ doc.party_name }}</p>
            <table class="table table-bordered table-condensed">
                <tr>
                    <th>Account Head</th>
                    <th width="150px" class="text-right">Net Balance</th>
                </tr>
                {% set adv_total = namespace(v=0) %}
                {% for row in advances %}
                <tr>
                    <td>{{ row.account }}</td>
                    <td class="text-right">{{ frappe.format(row.net_balance, {"fieldtype": "Currency"}) }}</td>
                </tr>
                {% set adv_total.v = adv_total.v + row.net_balance %}
                {% endfor %}
                <tr>
                    <td><strong>Total Outstanding</strong></td>
                    <td class="text-right"><strong>{{ frappe.format(adv_total.v, {"fieldtype": "Currency"}) }}</strong></td>
                </tr>
            </table>
        </div>
        {% endif %}

    {% endif %}
    {# ── End Outstanding Advances (Pay / Supplier or Employee) ── #}


    {# ══════════════════════════════════════════════════════════════════════════ #}
    {#                                                                            #}
    {#  RECEIVE (Customer) → Receivable Aging bucketed by age from posting_date  #}
    {#                                                                            #}
    {#  Buckets (measured in days from posting_date to today):                   #}
    {#    ≤ 365  days  → Up to 1 Year                                            #}
    {#    366–1825     → 2 to 5 Years                                            #}
    {#    > 1825 days  → 5+ Years                                                #}
    {#                                                                            #}
    {#  Shows: summary bucket table + full invoice detail with color coding      #}
    {#                                                                            #}
    {# ══════════════════════════════════════════════════════════════════════════ #}
    {% if doc.payment_type == "Receive" and doc.party_type == "Customer" and doc.party %}

        {% set today = frappe.utils.today() %}

        {% set receivables = frappe.db.sql("""
            SELECT
                name,
                posting_date,
                outstanding_amount,
                DATEDIFF(%s, posting_date) AS age_days
            FROM `tabSales Invoice`
            WHERE customer = %s
              AND docstatus = 1
              AND outstanding_amount > 0
            ORDER BY posting_date ASC
        """, (today, doc.party), as_dict=1) %}

        {% if receivables %}

        {# ── Bucket invoices by age ── #}
        {% set bucket_1yr   = [] %}
        {% set bucket_2to5  = [] %}
        {% set bucket_5plus = [] %}
        {% for inv in receivables %}
            {% if inv.age_days <= 365 %}
                {% set _ = bucket_1yr.append(inv) %}
            {% elif inv.age_days <= 1825 %}
                {% set _ = bucket_2to5.append(inv) %}
            {% else %}
                {% set _ = bucket_5plus.append(inv) %}
            {% endif %}
        {% endfor %}

        {# ── Bucket totals using namespace (Jinja2 scope-safe) ── #}
        {% set t1   = namespace(v=0) %}
        {% set t2   = namespace(v=0) %}
        {% set t5   = namespace(v=0) %}
        {% for inv in bucket_1yr   %} {% set t1.v  = t1.v  + inv.outstanding_amount %} {% endfor %}
        {% for inv in bucket_2to5  %} {% set t2.v  = t2.v  + inv.outstanding_amount %} {% endfor %}
        {% for inv in bucket_5plus %} {% set t5.v  = t5.v  + inv.outstanding_amount %} {% endfor %}
        {% set grand_total = t1.v + t2.v + t5.v %}

        <div class="margin-top">
            <p class="section-title">Receivable Aging — {{ doc.party_name }}</p>

            <div class="aging-legend">
                <span class="aging-1yr">■ Up to 1 Year</span>
                <span class="aging-2to5">■ 2 – 5 Years</span>
                <span class="aging-5plus">■ 5+ Years</span>
            </div>

            {# ── Bucket Summary ── #}
            <table class="table table-bordered table-condensed">
                <tr>
                    <th>Age Bucket</th>
                    <th width="70px" class="text-right"># Invoices</th>
                    <th width="150px" class="text-right">Outstanding</th>
                </tr>
                {% if bucket_1yr %}
                <tr class="aging-1yr">
                    <td>Up to 1 Year</td>
                    <td class="text-right">{{ bucket_1yr | length }}</td>
                    <td class="text-right">{{ frappe.format(t1.v, {"fieldtype": "Currency"}) }}</td>
                </tr>
                {% endif %}
                {% if bucket_2to5 %}
                <tr class="aging-2to5">
                    <td>2 – 5 Years</td>
                    <td class="text-right">{{ bucket_2to5 | length }}</td>
                    <td class="text-right">{{ frappe.format(t2.v, {"fieldtype": "Currency"}) }}</td>
                </tr>
                {% endif %}
                {% if bucket_5plus %}
                <tr class="aging-5plus">
                    <td>5+ Years</td>
                    <td class="text-right">{{ bucket_5plus | length }}</td>
                    <td class="text-right">{{ frappe.format(t5.v, {"fieldtype": "Currency"}) }}</td>
                </tr>
                {% endif %}
                <tr>
                    <td colspan="2"><strong>Grand Total Outstanding</strong></td>
                    <td class="text-right"><strong>{{ frappe.format(grand_total, {"fieldtype": "Currency"}) }}</strong></td>
                </tr>
            </table>

        </div>
        {% endif %}

    {% endif %}
    {# ── End Receivable Aging (Receive / Customer) ── #}


    {# ══════════════════════════════════════════════ #}
    {# ── Signature Footer ── #}
    {# ══════════════════════════════════════════════ #}
    <table style="width:100%; border-collapse:separate; border-spacing:0; margin-top:40px; border:none;">
        <tr>
            <td style="text-align:left; border:none;">
                {{ frappe.db.get_value("User", doc.owner, "full_name") }}
            </td>
            <td style="text-align:center; border:none;">
                CFO
            </td>
            <td style="text-align:right; border:none;">
                <!-- Approved By name if needed -->
            </td>
        </tr>
        <tr>
            <td style="text-align:left; border:none;">
                <div style="border-top:1px solid black; padding-top:8px; display:inline-block; text-align:center; min-width:150px;">
                    Prepared By
                </div>
            </td>
            <td style="text-align:center; border:none;">
                <div style="border-top:1px solid black; padding-top:8px; display:inline-block; min-width:150px;">
                    Checked By
                </div>
            </td>
            <td style="text-align:right; border:none;">
                <div style="border-top:1px solid black; padding-top:8px; display:inline-block; text-align:center; min-width:150px;">
                    Approved By
                </div>
            </td>
        </tr>
    </table>
</div>

{%- from "templates/print_formats/standard_macros.html" import add_header -%}

<style>
    .table-bordered td.top-bottom {
        border-top: none !important;
        border-bottom: none !important;
    }
    .table-bordered td.right {
        border-right: none !important;
    }
    .table-bordered td.left {
        border-left: none !important;
    }
</style>

<div>
    {# ── Dynamic heading based on payment_type ── #}
    {% if doc.payment_type == "Receive" %}
        {%- set _ = doc.set("select_print_heading", _("Receiving Entry")) -%}
    {% else %}
        {%- set _ = doc.set("select_print_heading", _("Payment Entry")) -%}
    {% endif %}

    {% set gl = frappe.get_list(
        doctype="GL Entry",
        fields=["account", "party_type", "party", "party_name", "debit", "credit", "remarks", "voucher_type", "account_currency", "against_voucher_type", "against_voucher"],
        filters={"voucher_type": doc.doctype, "voucher_no": doc.name}
    ) %}

    {{ add_header(0, 1, doc, letter_head, no_letterhead, print_settings) }}

    <div class="row margin-bottom">
        <div class="col-xs-6">
            <table>
                <tr>
                    <td><strong>Voucher No: </strong></td>
                    <td>{{ doc.name }}</td>
                </tr>
                <tr>
                    <td><strong>Type: </strong></td>
                    <td>{{ doc.payment_type }}
                    {% if doc.mode_of_payment %}
                    - {{ doc.mode_of_payment }}
                    {% endif %}
                    </td>
                </tr>
            </table>
        </div>

        <div class="col-xs-6">
            <table>
                <tr>
                    <td><strong>Date: </strong></td>
                    <td>{{ frappe.utils.format_date(doc.creation) }}</td>
                </tr>
                {% if doc.party %}
                <tr>
                    <td><strong>Party: </strong></td>
                    <td>
                        {{ doc.party_name }}<br>
                        <small>{{ doc.party_type }}/{{ doc.party }}</small>
                    </td>
                </tr>
                {% endif %}
            </table>
        </div>
    </div>

    <div class="margin-top">
        <table class="table table-bordered table-condensed">
            <tr>
                <th>Account</th>
                <th width="184px">Party</th>
                <th width="104px">Amount</th>
            </tr>

            {% for entries in gl %}
                {% if entries.debit > 0 %}
                <tr>
                    <td class="right top-bottom">
                        {{ entries.account }}<br>
                        <small>
                        {% if entries.against_voucher_type %}
                            <strong>Voucher Type:</strong>: {{ entries.against_voucher_type }}<br>
                        {% endif %}
                        {% if entries.against_voucher %}
                            <strong>Voucher#:</strong>: {{ entries.against_voucher }}<br>
                        {% endif %}
                        {% if doc.paid_to == entries.account %}
                            <strong>Balance</strong>: {{ frappe.format(doc.paid_to_account_balance, {"fieldtype": "Currency"}) }}<br>
                        {% endif %}
                        {% if doc.project %}
                            <strong>Project</strong><br>{{ doc.project }}: {{ frappe.db.get_value("Project", doc.project, "project_name") }}<br>
                        {% endif %}
                        <strong>Narration</strong>: {{ entries.remarks }}
                        </small>
                    </td>
                    <td class="right left top-bottom">
                        {% if entries.party_type == "Employee" %}
                            {{ frappe.db.get_value("Employee", entries.party, "employee_name") or "" }}<br>
                        {% elif entries.party_type == "Customer" %}
                            {{ frappe.db.get_value("Customer", entries.party, "customer_name") or "" }}<br>
                        {% elif entries.party_type == "Supplier" %}
                            {{ frappe.db.get_value("Supplier", entries.party, "supplier_name") or "" }}<br>
                        {% endif %}
                        <span style="font-size: 75%; display: block; text-align: left;">
                            {{ entries.party or "" }}
                        </span>
                    </td>
                    <td class="left top-bottom text-right">{{ frappe.format(entries.debit, {"fieldtype": "Currency"}) }}</td>
                </tr>
                {% endif %}
            {% endfor %}

            <tr>
                <td class="right" colspan="2"><strong>Total (debit)</strong></td>
                <td class="left text-right">{{ frappe.format((gl | sum(attribute="debit")), {"fieldtype": "Currency"}) }}</td>
            </tr>

            {% for entries in gl %}
                {% if entries.credit > 0 %}
                <tr>
                    <td class="right top-bottom">
                        {{ entries.account }}<br>
                        <small>
                        {% if entries.against_voucher_type %}
                            <strong>Voucher Type:</strong>: {{ entries.against_voucher_type }}<br>
                        {% endif %}
                        {% if entries.against_voucher %}
                            <strong>Voucher#:</strong>: {{ entries.against_voucher }}<br>
                        {% endif %}
                        {% if doc.paid_from == entries.account %}
                            <strong>Balance</strong>: {{ frappe.format(doc.paid_from_account_balance, {"fieldtype": "Currency"}) }}<br>
                        {% endif %}
                        {% if doc.project %}
                            <strong>Project</strong><br>{{ doc.project }}: {{ frappe.db.get_value("Project", doc.project, "project_name") }}
                        {% endif %}
                        <strong>Narration</strong>: {{ entries.remarks }}
                        </small>
                    </td>
                    <td class="right left top-bottom">{{ entries.party or "" }}</td>
                    <td class="left top-bottom text-right">{{ frappe.format(entries.credit, {"fieldtype": "Currency"}) }}</td>
                </tr>
                {% endif %}
            {% endfor %}

            <tr>
                <td class="right" colspan="2"><strong>Total (credit)</strong></td>
                <td class="left text-right">{{ frappe.format((gl | sum(attribute="credit")), {"fieldtype": "Currency"}) }}</td>
            </tr>
        </table>
    </div>

    {# ── Allocated Sales Invoices — only for Receipt Voucher ── #}
    {% if doc.payment_type == "Receive" and doc.references and doc.references|length > 0 %}
        {% set has_si = [] %}
        {% for ref in doc.references %}
            {% if ref.reference_doctype == "Sales Invoice" %}
                {% set _ = has_si.append(1) %}
            {% endif %}
        {% endfor %}

        {% if has_si|length > 0 %}
        <div class="margin-top">
            <table class="table table-bordered table-condensed">
                <tr>
                    <th>Invoice No</th>
                    <th>Description</th>
                    <th width="104px">Allocated Amount</th>
                </tr>

                {% for ref in doc.references %}
                {% if ref.reference_doctype == "Sales Invoice" %}

                    {% set inv = frappe.get_doc("Sales Invoice", ref.reference_name) if ref.reference_name else None %}
                    {% set item_desc = "—" %}

                    {% if inv and inv.items and inv.items|length > 0 %}
                        {% for item in inv.items %}
                            {% if item_desc == "—" and item.description and item.description.strip() %}
                                {% set raw_desc = item.description | trim | replace('\r\n', '\n') %}
                                {% set lines = raw_desc.split('\n') %}
                                {% set cleaned = [] %}
                                {% for line in lines %}
                                    {% if line.strip() %}
                                        {% set cleaned = cleaned + [line | trim] %}
                                    {% endif %}
                                {% endfor %}
                                {% set item_desc = cleaned | join(' ') if cleaned else item.item_name %}
                            {% endif %}
                        {% endfor %}
                        {% if item_desc == "—" %}
                            {% set item_desc = inv.items[0].item_name or "—" %}
                        {% endif %}
                    {% endif %}

                    <tr>
                        <td class="right top-bottom">{{ ref.reference_name }}</td>
                        <td class="right left top-bottom">{{ item_desc }}</td>
                        <td class="left top-bottom text-right">{{ frappe.format(ref.allocated_amount, {"fieldtype": "Currency"}) }}</td>
                    </tr>

                {% endif %}
                {% endfor %}
            </table>
        </div>
        {% endif %}
    {% endif %}
    {# ── End Allocated Sales Invoices ── #}

    <table>
        <tr>
            <td>Reference No:</td>
            <td>{{ doc.reference_no or "-" }}</td>
        </tr>
        <tr>
            <td>Reference Date:</td>
            <td>{{ doc.reference_date or "-" }}</td>
        </tr>
        <tr>
            <td>Amount in Words:</td>
            <td>{{ doc.get_formatted("base_in_words") }}</td>
        </tr>
    </table>

    <table style="width:100%; border-collapse:separate; border-spacing:0; margin-top:40px; border:none;">
        <tr>
            <td style="text-align:left; border:none;">
                {{ frappe.db.get_value("User", doc.owner, "full_name") }}
            </td>
            <td style="text-align:center; border:none;">
                CFO
            </td>
            <td style="text-align:right; border:none;">
                <!-- Approved By name if needed -->
            </td>
        </tr>
        <tr>
            <td style="text-align:left; border:none;">
                <div style="border-top:1px solid black; padding-top:8px; display:inline-block; text-align:center; min-width:150px;">
                    Prepared By
                </div>
            </td>
            <td style="text-align:center; border:none;">
                <div style="border-top:1px solid black; padding-top:8px; display:inline-block; min-width:150px;">
                    Checked By
                </div>
            </td>
            <td style="text-align:right; border:none;">
                <div style="border-top:1px solid black; padding-top:8px; display:inline-block; text-align:center; min-width:150px;">
                    Approved By
                </div>
            </td>
        </tr>
    </table>
</div>

{% for row in doc.items %}
    {% set item_code = row.item_code %}
    {% set item_name = frappe.db.get_value("Item", item_code, "item_name") %}

    {% if row.serial_no %}
        {% set serial_nos = row.serial_no.split(",") %}
        {% for sn in serial_nos %}
            <table style="width:100% !important;">
                <tbody>
                    <tr>
 <td class="" style="font-size: 12px; width:100%;">
                        <div style="text-align:center;"> 
                        <div style="width:76px;height:76px;margin:auto;margin-bottom:4px;">
                            <img style="width:76px;height:76px;" src="http://bwipjs-api.metafloor.com/?bcid=qrcode&amp;text={{ sn }}">
                        </div>
                        <div>{{ sn }}</div>
                        </div>
                    </td>
                        <td style="width:50%"></td>
                    </tr>
                </tbody>
            </table>
            <div class="new-page"></div>
        {% endfor %}

    {% elif row.serial_and_batch_bundle %}
        {% set bundle_doc = frappe.get_doc("Serial and Batch Bundle", row.serial_and_batch_bundle) %}
        {% for entry in bundle_doc.entries %}
            {% if entry.serial_no %}
                <table style="width:100% !important;">
                    <tbody>
                        <tr>
                             <td class="" style="font-size: 12px; width:100%;">
                        <div style="text-align:center;"> 
                        <div style="width:76px;height:76px;margin:auto;margin-bottom:4px;">
                            <img style="width:76px;height:76px;" src="http://bwipjs-api.metafloor.com/?bcid=qrcode&amp;text={{ entry.serial_no }}">
                        </div>
                        <div>{{ entry.serial_no }}</div>
                        </div>
                    </td>
                            <td style="width:50%"></td>
                        </tr>
                    </tbody>
                </table>
                <div class="new-page"></div>
            {% endif %}
        {% endfor %}
    {% endif %}
{% endfor %}

